Lemma cb_split3_gen : forall m A n1 n2 n3 (bs1 bs2 bs3 : list byte),
  length bs1 = n1 -> length bs2 = n2 -> length bs3 = n3 ->
  rw_cells asegs m A [CB (n1 + n2 + n3)%nat (bs1 ++ bs2 ++ bs3)] ->
  rw_cells asegs m A [CB n1 bs1] /\ rw_cells asegs m (A + Z.of_nat n1) [CB n2 bs2] /\ rw_cells asegs m (A + Z.of_nat n1 + Z.of_nat n2) [CB n3 bs3].
